import { getCustomer } from './customers.js';
import { formatEuros } from './money.js';
import { lineTotal, lineDiscount, lineBulkDiscount, invoiceTotals } from './invoices.js';
import { balanceDue } from './payments.js';

/**
 * Render an invoice as plain text.
 * @param {{ customerId: string, number?: string, status?: string, dueDate?: string, lines: Array<any>, payments?: Array<any>, voucher?: any }} invoice
 * @returns {string}
 */
export function renderInvoiceText(invoice) {
  const customerResult = getCustomer(invoice.customerId);
  if (!customerResult.ok) {
    throw new Error(`Customer not found: ${invoice.customerId}`);
  }

  const customer = customerResult.value;
  const { subtotal, discount, vat, voucher, total } = invoiceTotals(invoice);

  const lines = [
    invoice.number || 'DRAFT',
    customer.name,
    ...invoice.lines.map((line) => {
      const lt = lineTotal(line);
      const ld = lineDiscount(line);
      const bd = lineBulkDiscount(line);
      const lineDiscountTotal = ld + bd;

      let lineStr = `${line.qty} x ${line.name} @ ${formatEuros(line.unitPrice)} = ${formatEuros(lt)}`;
      if (lineDiscountTotal > 0) {
        lineStr += ` (-${formatEuros(lineDiscountTotal)})`;
      }
      return lineStr;
    }),
  ];

  if (subtotal > 0) {
    lines.push(`Subtotal: ${formatEuros(subtotal)}`);
  }

  if (discount > 0) {
    lines.push(`Discount: -${formatEuros(discount)}`);
  }

  if (vat > 0) {
    lines.push(`VAT: ${formatEuros(vat)}`);
  }

  if (voucher > 0) {
    lines.push(`Voucher: -${formatEuros(voucher)}`);
  }

  lines.push(`Total: ${formatEuros(total)}`);

  if (invoice.dueDate) {
    lines.push(`Due: ${invoice.dueDate}`);
  }

  const paid = invoice.payments?.reduce((sum, p) => sum + p.amount, 0) ?? 0;
  if (paid > 0) {
    lines.push(`Paid: ${formatEuros(paid)}`);
  }

  return lines.join('\n');
}

