test('renderInvoiceText shows line discount when present', () => {
  const r = createInvoice({
    customerId: 'C-002',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 5, discountPercent: 10 }],
  });
  const text = renderInvoiceText(r.value);
  assert.match(text, /\(-€/);
});

test('renderInvoiceText shows line discount amount correctly', () => {
  const r = createInvoice({
    customerId: 'C-002',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 5, discountPercent: 10 }],
  });
  const text = renderInvoiceText(r.value);
  // 5 * 8500 = 42500, discount 10% = 4250
  assert.match(text, /\(-€42\.50\)/);
});

test('renderInvoiceText does not show discount for lines without discount', () => {
  const r = createInvoice({
    customerId: 'C-002',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 1 }],
  });
  const text = renderInvoiceText(r.value);
  const lines = text.split('\n');
  const lineItems = lines.filter((l) => l.includes('Development'));
  assert(lineItems[0].endsWith('€95.00'));
});

test('renderInvoiceText shows bulk discount on line', () => {
  const r = createInvoice({
    customerId: 'C-002',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 10 }],
  });
  const text = renderInvoiceText(r.value);
  // 10 * 9500 = 95000, bulk discount 2.5% = 2375
  assert.match(text, /\(-€23\.75\)/);
});

test('renderInvoiceText shows both line and bulk discount', () => {
  const r = createInvoice({
    customerId: 'C-002',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 10, discountPercent: 5 }],
  });
  const text = renderInvoiceText(r.value);
  // Line discount: 95000 * 5% = 4750
  // Bulk discount: 90250 * 2.5% = 2256.25 = 2256
  // Total: 4750 + 2256 = 7006
  assert.match(text, /\(-€70\.06\)/);
});

test('renderInvoiceText shows due date when present', () => {
  const r = createInvoice({
    customerId: 'C-002',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 1 }],
    terms: 'NET14',
  });
  const issued = issueInvoice(r.value, []);
  const text = renderInvoiceText(issued.value);
  assert.match(text, /Due: 2026-10-21/);
});

test('renderInvoiceText does not show due date for draft', () => {
  const r = createInvoice({
    customerId: 'C-002',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 1 }],
  });
  const text = renderInvoiceText(r.value);
