      { sku: 'DEV-HOUR', qty: 10 },
      { sku: 'DES-HOUR', qty: 5 },
      { sku: 'COPY-HOUR', qty: 3 },
    ],
  });
  const text = renderInvoiceText(r.value);
  const lines = text.split('\n');
  assert.equal(lines[0], 'DRAFT');
  assert.equal(lines[1], 'Kite & Co');
  // DRAFT + name + 3 line items (with bulk discount shown) + subtotal + discount + VAT + total + due = 10 lines
  assert.equal(lines.length, 10);
  const totalIndex = lines.findIndex((l) => l.startsWith('Total:'));
  const dueIndex = lines.findIndex((l) => l.startsWith('Due:'));
  assert(totalIndex !== -1);
  assert(dueIndex !== -1);
  assert(totalIndex < dueIndex);
});

