      { sku: 'DEV-HOUR', qty: 5 },      // 21% VAT, no bulk discount (qty < 10)
      { sku: 'PRINT-A4', qty: 10 },     // 9% VAT, bulk discount applies
    ],
  });
  const text = renderInvoiceText(r.value);
  // DEV-HOUR: 5 * 9500 = 47500, VAT = 9975
  // PRINT-A4: 10 * 37 = 370, bulk discount = 9, after = 361, VAT = 32
  // subtotal = 47870, discount = 9, vat = 10007, total = 57868
  assert.match(text, /Subtotal: €478\.70/);
  assert.match(text, /VAT: €100\.07/);
  assert.match(text, /Total: €578\.68/);
});

