  // DRAFT + name + 3 line items (with bulk discount shown) + subtotal + discount + VAT + total + due = 10 lines
  assert.equal(lines.length, 10);
  const totalIndex = lines.findIndex((l) => l.startsWith('Total:'));
  const dueIndex = lines.findIndex((l) => l.startsWith('Due:'));
